    WHERE dg.strategy_id = s.id
    ) < now() - interval '1 hour'
    ORDER BY (
    SELECT max(dg.created_at)
    FROM public.csv_daily_returns dg
    WHERE dg.strategy_id = s.id
    ) ASC
    LIMIT 100
    ON CONFLICT (strategy_id, generation_key) DO NOTHING;

